import {icon,esc,state,save,activity,courses,course,lastScore,levelLabel,toast,go,empty,btn,heading,progressBar} from './core.js';
const shuffled=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const r=new Uint32Array(1);crypto.getRandomValues(r);const j=r[0]%(i+1);[b[i],b[j]]=[b[j],b[i]];}return b;};
function newDraft(c,key,practice){const selected=practice?Object.values(state.mistakes).filter(m=>m.courseId===c.id).map(m=>m.question):c.questions;return state.drafts[key]={courseId:c.id,mode:practice?'practice':'normal',index:0,answers:{},questions:selected.map(q=>{const order=shuffled([0,1,2,3]);return {...q,opts:order.map(i=>q.opts[i]),correct:order.indexOf(q.correct)};}),started:new Date().toISOString()};}
export function renderQuizList(){const list=courses.filter(c=>c.questions.length);return heading('แบบทดสอบความเข้าใจ','บทละ 15 ข้อ · ง่าย 7 ข้อ · ปานกลาง 5 ข้อ · ยาก 3 ข้อ')+`<div class="quiz-list">${list.map(c=>{const a=lastScore(c),d=state.drafts[c.id];return `<article class="panel quiz-intro"><div class="stat-icon">${icon(c.icon)}</div><div><span class="eyebrow" style="margin-bottom:5px">CHAPTER ${String(c.n).padStart(2,'0')}</span><h3>${esc(c.title)}</h3><p>${esc(c.thai)}</p><div class="pills"><span class="pill easy">ง่าย 7</span><span class="pill medium">ปานกลาง 5</span><span class="pill hard">ยาก 3</span></div><div class="inline-actions"><a class="button primary small" href="#quiz/${c.id}">${d?'ทำต่อ · '+Object.keys(d.answers).length+'/15':'เริ่มทำแบบทดสอบ'} ${icon('arrow')}</a><span class="muted" style="font-size:10px">${a?'ล่าสุด '+a.score+'/15':'ยังไม่ได้ทำ'}</span></div></div></article>`;}).join('')}</div><p class="bottom-note">${icon('shield')}เฉลยจะแสดงหลังส่งคำตอบ · คำตอบที่ยังทำไม่เสร็จบันทึกอัตโนมัติ</p>`;}
export function renderQuiz(key){const practice=key?.startsWith('practice-'),id=practice?key.slice(9):key,c=course(id);if(!c||!c.questions.length)return empty('ยังไม่มีแบบทดสอบสำหรับบทนี้','เลือกบทเรียนที่มีชุดคำถามจากคลังแบบทดสอบ',`<a class="button primary" href="#quizzes">เลือกแบบทดสอบ</a>`);if(practice&&!state.drafts[key]&&!Object.values(state.mistakes).some(m=>m.courseId===id))return empty('ทบทวนข้อที่ผิดครบแล้ว','กลับไปเรียนหรือทำแบบทดสอบหลักอีกครั้ง',`<a class="button primary" href="#quizzes">ไปแบบทดสอบ</a>`);const d=state.drafts[key]||newDraft(c,key,practice);save();const n=d.questions.length,i=Math.max(0,Math.min(n-1,d.index)),q=d.questions[i],answered=Object.keys(d.answers).length;return `<div class="quiz-area"><a class="back-link" href="${practice?'#mistakes':'#quizzes'}">${icon('back')}${practice?'กลับสมุดข้อผิดพลาด':'กลับแบบทดสอบ'}</a><div class="quiz-header"><div><h1>${esc(c.title)}</h1><p>${practice?'ฝึกเฉพาะข้อที่เคยตอบผิด':'แบบทดสอบประจำบท'} · ตอบแล้ว ${answered}/${n} ข้อ</p></div>${btn(icon('x')+'พักไว้ก่อน',`data-quiz-exit="${practice?'mistakes':'quizzes'}"`,'small ghost')}</div>${progressBar(answered/n*100)}<div class="question-nav" aria-label="เลือกข้อคำถาม">${d.questions.map((v,j)=>`<button class="q-number ${d.answers[v.id]!==undefined?'answered':''} ${j===i?'current':''}" data-q-index="${j}" data-draft="${key}" aria-label="ข้อ ${j+1}${d.answers[v.id]!==undefined?' ตอบแล้ว':''}" aria-current="${j===i?'step':'false'}">${j+1}</button>`).join('')}</div><section class="panel question-card"><div class="result-tags"><span class="pill ${q.level}">${levelLabel[q.level]}</span><span class="muted" style="font-size:10px">ข้อ ${i+1} จาก ${n}</span></div><h2>${esc(q.q)}</h2><div class="answer-options" role="group" aria-label="ตัวเลือกคำตอบ">${q.opts.map((o,j)=>`<button class="answer ${d.answers[q.id]===j?'chosen':''}" data-answer="${j}" data-question="${q.id}" data-draft="${key}" aria-pressed="${d.answers[q.id]===j}"><span class="letter">${'ABCD'[j]}</span><span>${esc(o)}</span>${d.answers[q.id]===j?`<span style="margin-left:auto;color:var(--accent)">${icon('check')}</span>`:''}</button>`).join('')}</div></section><div class="quiz-footer">${btn(icon('back')+'ข้อก่อนหน้า',`data-q-index="${i-1}" data-draft="${key}" ${i===0?'disabled':''}`,'ghost')}${i<n-1?btn('ข้อถัดไป'+icon('arrow'),`data-q-index="${i+1}" data-draft="${key}"`,'primary'):btn('ส่งคำตอบ '+answered+'/'+n+icon('check'),`data-submit-quiz="${key}" ${answered<n?'disabled':''}`,'primary')}</div>${i===n-1&&answered<n?`<p class="quiz-save">ยังเหลือ ${n-answered} ข้อ เลือกหมายเลขข้อด้านบนเพื่อกลับไปตอบให้ครบ</p>`:''}<p class="quiz-save">${icon('shield')}บันทึกคำตอบอัตโนมัติ · กลับมาทำต่อได้ในเบราว์เซอร์นี้</p></div>`;}
function submit(key){const d=state.drafts[key];if(!d||Object.keys(d.answers).length<d.questions.length){toast('กรุณาตอบให้ครบทุกข้อก่อนส่ง');return;}const questions=structuredClone(d.questions);let score=0;for(const q of questions){const k=d.courseId+':'+q.id;if(d.answers[q.id]===q.correct){score++;delete state.mistakes[k];}else{state.mistakes[k]={courseId:d.courseId,question:{...q},answer:d.answers[q.id],date:new Date().toISOString()};}}const id=crypto.randomUUID();state.attempts.push({id,courseId:d.courseId,score,total:questions.length,mode:d.mode,questions,answers:{...d.answers},date:new Date().toISOString()});delete state.drafts[key];activity().quizzes++;save();go('#result/'+id);}
export function renderResult(id){const a=state.attempts.find(x=>x.id===id);if(!a)return empty('ไม่พบผลสอบนี้','เลือกชุดคำถามจากหน้าแบบทดสอบ',`<a class="button" href="#quizzes">เลือกแบบทดสอบ</a>`);const c=course(a.courseId),percent=Math.round(a.score/a.total*100),byLevel=['easy','medium','hard'].map(l=>{const q=a.questions.filter(q=>q.level===l);return {l,total:q.length,correct:q.filter(q=>a.answers[q.id]===q.correct).length};});return `<div class="quiz-area"><a class="back-link" href="#quizzes">${icon('back')}กลับแบบทดสอบ</a><section class="panel result-hero"><div><div class="eyebrow">YOUR LEARNING CHECKPOINT</div><h2>${percent>=80?'เข้าใจมากขึ้นอีกขั้นแล้ว!':percent>=50?'มาถูกทางแล้ว ลองทบทวนอีกนิด':'ทุกครั้งที่ลอง คือโอกาสเข้าใจเพิ่ม'}</h2><p>${esc(c?.title||'ผลแบบทดสอบ')} · ${a.mode==='practice'?'ฝึกทบทวน':'แบบทดสอบประจำบท'}</p><div class="inline-actions" style="margin-top:15px;flex-wrap:wrap">${byLevel.filter(l=>l.total).map(l=>`<span class="pill ${l.l}">${levelLabel[l.l]} ${l.correct}/${l.total}</span>`).join('')}</div></div><div class="result-score">${a.score}<small> / ${a.total}</small><div style="font-size:12px;letter-spacing:0;text-align:center;margin-top:9px">${percent}%</div></div></section><div class="section-heading"><h2>เฉลยและคำอธิบาย</h2><a class="text-link" href="#mistakes">สมุดข้อผิดพลาด ${icon('arrow')}</a></div>${a.questions.map((q,i)=>{const ok=a.answers[q.id]===q.correct;return `<article class="panel result-item"><div class="result-tags"><span class="pill ${q.level}">${levelLabel[q.level]}</span><span class="${ok?'correct-label':'wrong-label'}">${icon(ok?'check':'x')} ${ok?'ตอบถูก':'ลองทบทวนอีกครั้ง'}</span></div><h3>${i+1}. ${esc(q.q)}</h3>${!ok?`<div class="result-answer wrong">คำตอบของคุณ: ${esc(q.opts[a.answers[q.id]])}</div>`:''}<div class="result-answer">คำตอบที่ถูก: ${esc(q.opts[q.correct])}</div><p>${esc(q.explanation)}</p><a class="source-link" href="#summary/${a.courseId}">${icon('file')}ทบทวนสรุปบทนี้ ${icon('arrow')}</a></article>`;}).join('')}<div class="summary-actions"><a class="button ghost" href="#summary/${a.courseId}">${icon('book')}ทบทวนสรุป</a><a class="button primary" href="#quiz/${a.courseId}">${icon('quiz')}ลองทำอีกครั้ง</a></div></div>`;}
export function renderMistakes(){const mistakes=Object.entries(state.mistakes),groups=[...new Set(mistakes.map(([,m])=>m.courseId))];return heading('สมุดข้อผิดพลาด','เปลี่ยนข้อที่เคยพลาด ให้กลายเป็นเรื่องที่เข้าใจ')+`${groups.length?`<div class="inline-actions" style="flex-wrap:wrap;margin-bottom:24px">${groups.map(id=>`<a class="button small" href="#quiz/practice-${id}">${icon('quiz')}ฝึก ${esc(course(id)?.title||id)}</a>`).join('')}</div>`:''}<div class="saved-grid">${mistakes.length?mistakes.map(([k,m])=>`<article class="panel saved-card"><div class="result-tags"><span class="pill ${m.question.level}">${levelLabel[m.question.level]}</span><small class="muted">${esc(course(m.courseId)?.title||'บทเรียน')}</small></div><h3>${esc(m.question.q)}</h3><div class="result-answer wrong">เคยตอบ: ${esc(m.question.opts[m.answer])}</div><div class="result-answer">คำตอบที่ถูก: ${esc(m.question.opts[m.question.correct])}</div><p>${esc(m.question.explanation)}</p><div class="saved-actions"><a class="text-link" href="#summary/${m.courseId}">อ่านสรุปบทนี้ ${icon('arrow')}</a><button class="button small ghost" data-mastered="${esc(k)}">${icon('check')}เข้าใจแล้ว</button></div></article>`).join(''):empty('ยังไม่มีข้อที่ต้องทบทวน','ข้อที่ตอบผิดจะถูกรวมไว้ที่นี่หลังส่งแบบทดสอบ',`<a class="button primary" href="#quizzes">เริ่มทำแบบทดสอบ ${icon('arrow')}</a>`)}</div>`;}
export async function handleQuizClick(b){if(b.dataset.quizExit){go('#'+b.dataset.quizExit);return;}if(b.dataset.qIndex!==undefined){const d=state.drafts[b.dataset.draft];if(!d)return;d.index=Math.max(0,Math.min(d.questions.length-1,Number(b.dataset.qIndex)));save();go(location.hash);}if(b.dataset.answer!==undefined){const d=state.drafts[b.dataset.draft];if(!d)return;d.answers[b.dataset.question]=Number(b.dataset.answer);save();go(location.hash);}if(b.dataset.submitQuiz)submit(b.dataset.submitQuiz);if(b.dataset.mastered){delete state.mistakes[b.dataset.mastered];save();go(location.hash);toast('บันทึกว่าเข้าใจแล้ว');}}
